refentry.refsect1:
  &reftitle.returnvalues;

hashed string return गर्दछ, वा असफलतामा १३ character भन्दा छोटो हुने र salt from फरक हुने सुनिश्चित गरिएको एउटा string return गर्दछ।

   Password हरू validate गर्दा, crypt को output लाई पहिले थाहा भएको hash सँग तुलना गर्न timing attacks प्रति vulnerable नभएको एउटा string comparison function प्रयोग गरिनुपर्छ। यस उद्देश्यका लागि PHP ले hash_equals प्रदान गर्दछ।

  &reftitle.examples;



    crypt का उदाहरणहरू


<?php
$user_input = 'rasmuslerdorf';
$hashed_password = '$6$rounds=1000000$NJy4rIPjpOaU$0ACEYGg/aKCY3v8O8AfyiO7CTfZQ8/W231Qfh2tRLmfdvFD6XfHk12u6hMr9cYIA4hnpjLNSTRtUwYr9km9Ij/';

// Validate an existing crypt() hash in a way that is compatible with non-PHP software.
if (hash_equals($hashed_password, crypt($user_input, $hashed_password))) {
   echo "Password verified!";
}
?>
